from __future__ import annotations

from dataclasses import replace
from datetime import datetime, timezone

import pytest

from gitseed.application import execute
from gitseed.collect.search import Candidate, CollectResult
from gitseed.grade.types import GradeResult
from gitseed.pipeline.run import FetchedFiles
from gitseed.ports import RepositoryMetadata, RunPorts, RunRequest
from gitseed.scoring import ScoreInputs
from gitseed.storage import SQLiteRunStore, StoredRun


AT = datetime(2026, 7, 27, 12, 0, tzinfo=timezone.utc)
CANDIDATE = Candidate(
    repo="org/repo",
    owner="org",
    html_url="https://github.com/org/repo",
    stars=4,
    pushed_at="2026-07-27T00:00:00Z",
)


class Repository:
    def __init__(self, candidate: Candidate) -> None:
        self.candidate = candidate

    def search(self, query: str, limit: int) -> CollectResult:
        return CollectResult(candidates=[self.candidate], pages_fetched=1)

    def metadata(self, candidate: Candidate, at: datetime) -> RepositoryMetadata:
        return RepositoryMetadata(ScoreInputs(True, True, True))


class Files:
    def read(self, candidate: Candidate) -> FetchedFiles:
        return FetchedFiles((("main.py", "def add(a, b):\n    return a + b\n"),))


class Model:
    def evaluate(self, digest: str) -> GradeResult:
        return GradeResult(8, 7, "small utility", "fixture", 0.0, "fixture-v1")

    def flags_malicious(self, digest: str) -> bool:
        return False


class Clock:
    def now(self) -> datetime:
        return AT


def make_artifact(stars: int):
    candidate = replace(CANDIDATE, stars=stars)
    return execute(
        RunRequest("small tools", 1),
        RunPorts(Repository(candidate), Files(), Model(), Clock()),
    )


def stored_run_lookup(store: SQLiteRunStore):
    """Find any public point-lookup API without imposing an API name."""
    operations = []
    if hasattr(store, "__getitem__"):
        operations.append(store.__getitem__)

    for name in dir(store):
        if name.startswith("_"):
            continue
        member = getattr(store, name)
        if callable(member):
            operations.append(member)
        elif hasattr(member, "__getitem__"):
            operations.append(member.__getitem__)

    for lookup in operations:
        try:
            result = lookup("corrected-run")
        except (KeyError, TypeError):
            continue
        if isinstance(result, StoredRun):
            return lookup

    raise AssertionError("SQLiteRunStore exposes no public point lookup that returns StoredRun")


def test_point_lookup_returns_correction_metadata_and_reports_missing_runs(tmp_path) -> None:
    original = make_artifact(stars=4)
    corrected = make_artifact(stars=9)
    assert original.to_bytes() != corrected.to_bytes()

    with SQLiteRunStore(tmp_path / "runs.db") as store:
        store.save("original-run", original)
        store.save("corrected-run", corrected, corrects_run_id="original-run")

        lookup = stored_run_lookup(store)
        stored = lookup("corrected-run")

        assert stored.run_id == "corrected-run"
        assert stored.corrects_run_id == "original-run"
        assert stored.artifact.to_bytes() == corrected.to_bytes()

        with pytest.raises(KeyError) as missing:
            lookup("missing-run")

    assert missing.value.args == ("missing-run",)
